<?php
session_start();require_once __DIR__.'/config/database.php';
$id=(int)($_GET['id']??0);if($id<1){header('Location: categories.php');exit;}
$s=$conn->prepare("SELECT p.*,c.name category_name,b.name brand_name FROM products p LEFT JOIN categories c ON p.category_id=c.id LEFT JOIN brands b ON p.brand_id=b.id WHERE p.id=? LIMIT 1");$s->bind_param("i",$id);$s->execute();$product=$s->get_result()->fetch_assoc();if(!$product){header('Location: categories.php');exit;}
$error=$_GET['error']??'';$message=$_GET['message']??'';$cartCount=array_sum(array_map('intval',$_SESSION['cart']??[]));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($product['name'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body>
<nav class="navbar main-navbar"><div class="container"><a class="navbar-brand text-white fw-bold" href="index.php">SmartStore</a><a class="text-white text-decoration-none" href="cart.php">Cart <span class="cart-nav-count"><?=$cartCount?></span></a></div></nav>
