<div class="product-detail-card mt-4"><div class="row g-0"><div class="col-lg-6 product-detail-image"><?php if($product['image']):?><img src="admin/assets/images/products/<?=htmlspecialchars($product['image'])?>" alt="<?=htmlspecialchars($product['name'])?>"><?php else:?><i class="bi bi-image fs-1"></i><?php endif;?></div><div class="col-lg-6 p-4 p-md-5 d-flex flex-column"><small class="text-custom-primary fw-bold"><?=htmlspecialchars($product['category_name']??'Product')?><?=!empty($product['brand_name'])?' · '.htmlspecialchars($product['brand_name']):''?></small><h1 class="fw-bold text-dark-custom mt-2"><?=htmlspecialchars($product['name'])?></h1><p class="text-muted flex-grow-1"><?=nl2br(htmlspecialchars($product['description']??'No description available.'))?></p><div class="product-detail-price">$<?=number_format((float)$product['price'],2)?></div><p class="text-muted">Stock: <?=intval($product['stock'])?></p><?php if($product['stock']>0):?><form action="add-to-cart.php" method="post" class="row g-2"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="buy_now" value="1"><div class="col-4"><input class="form-control" type="number" name="quantity" value="1" min="1" max="<?=intval($product['stock'])?>"></div><div class="col-8"><button class="btn custom-primary w-100">Order Now</button></div></form><?php else:?><button class="btn btn-secondary w-100" disabled>Out of Stock</button><?php endif;?></div></div></div></main></body></html>